'use strict';
let currentLesson=null,exerciseIndex=0,answered=false,built=[];
function grammarItems(){const folder=$('#grammar-folder').value;return ImportHub.collections('grammar').find(c=>c.id===folder)?.items||[];}
function renderGrammarFolders(){const old=$('#grammar-folder').value,collections=ImportHub.collections('grammar');$('#grammar-folder').innerHTML=collections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')||'<option value="">Import tài liệu / Dokument importieren</option>';if(collections.some(c=>c.id===old))$('#grammar-folder').value=old;$('#grammar-folder').disabled=!collections.length;}
function renderLessonList(){const level=$('#grammar-level').value;const items=grammarItems().filter(l=>level==='all'||!l.level||l.level===level);const completed=Auth.get('lessons',{});$('#lesson-list').innerHTML=items.map(l=>`<details class="grammar-topic" ${currentLesson?.id===l.id?'open':''}><summary>📁 ${esc(l.title)} ${completed[l.id]?'✓':''}</summary><p class="help-text">${esc(l.level||'—')} · ${l.exercises?.length||0} Übungen</p><button class="secondary full" data-id="${esc(l.id)}">${esc(App.t('start'))} →</button></details>`).join('')||`<p>${esc(App.t('empty'))}</p>`;$('#lesson-list').querySelectorAll('button').forEach(b=>b.onclick=()=>openLesson(b.dataset.id));}
function openLesson(id){currentLesson=grammarItems().find(l=>l.id===id)||null;exerciseIndex=0;renderLesson();renderLessonList();}
function lessonText(value){if(typeof value==='string')return value;return value?.[App.settings().language]||value?.de||value?.vi||'';}
function renderLesson(){const l=currentLesson;if(!l){$('#lesson-panel').innerHTML=`<div class="empty-state">✦<p>${esc(App.t('empty'))}</p></div>`;return;}$('#lesson-panel').innerHTML=`<span class="tag">${esc(l.level||'GRAMMATIK')} · ELIO</span><h2 style="font-size:27px;margin:15px 0">${esc(l.title)}</h2><div class="learning-content">${esc(lessonText(l.content))}</div>${Array.isArray(l.aiAdditions)&&l.aiAdditions.length?`<details open class="ai-addition"><summary>✦ AI bổ sung / AI additions / KI-Ergänzung</summary>${l.aiAdditions.map(a=>`<div class="learning-content">${esc(typeof a==='string'?a:a.content||'')}</div>`).join('')}</details>`:''}<button id="grammar-enrich" class="secondary">✦ Bổ sung lý thuyết & bài tập / Ergänzen / Enrich</button><p id="grammar-enrich-status" role="status">${esc(l.enrichmentError||'')}</p>${l.examples?`<div class="example-box">${esc(l.examples)}</div>`:''}<div id="grammar-exercise" class="exercise-box"></div>`;$('#grammar-enrich').onclick=enrichCurrentLesson;renderExercise();}
function renderExercise(){const exercises=Array.isArray(currentLesson.exercises)?currentLesson.exercises:[];const target=$('#grammar-exercise');answered=false;built=[];if(!exercises.length){target.innerHTML='<p>Chưa có bài tập / No exercises yet. ✦ AI có thể tạo thêm bài tập cho chủ điểm này.</p>';return;}if(exerciseIndex>=exercises.length){target.innerHTML=`<h3>${esc(App.t('complete'))} ✧</h3><button id="complete-lesson">${esc(App.t('complete'))} +20 XP</button>`;$('#complete-lesson').onclick=()=>{if(!Auth.require())return;const state=Auth.get('lessons',{});state[currentLesson.id]={completedAt:Date.now(),level:currentLesson.level};Auth.set('lessons',state);App.event('lesson:'+currentLesson.id,'grammar',20,currentLesson.tag||currentLesson.title);renderLessonList();toast(App.t('complete')+' ✓');};return;}const ex=exercises[exerciseIndex];target.innerHTML=`<span class="tag">${exerciseIndex+1} / ${exercises.length} · ${ex.origin==='ai'?'AI':'Tài liệu / Quelle'}</span><h3>${esc(ex.question||ex.content||'Übung')}</h3><div id="exercise-controls"></div><div id="exercise-feedback" aria-live="polite"></div>`;const controls=$('#exercise-controls');
if(ex.type==='quiz'&&Array.isArray(ex.options)){controls.innerHTML=`<div class="options">${ex.options.map((v,i)=>`<button data-answer="${i}">${esc(v)}</button>`).join('')}</div>`;controls.querySelectorAll('button').forEach(b=>b.onclick=()=>checkExercise(ex.options[Number(b.dataset.answer)]));}
else if(ex.type==='build'&&Array.isArray(ex.tokens)){const indices=ex.tokens.map((_,i)=>i).sort(()=>Math.random()-.5);controls.innerHTML=`<div id="built-sentence" class="example-box">…</div><div class="chat-tools">${indices.map(i=>`<button class="secondary" data-token="${i}">${esc(ex.tokens[i])}</button>`).join('')}</div><div class="chat-tools"><button id="reset-build" class="secondary">↶</button><button id="check-build">${esc(App.t('submit'))}</button></div>`;controls.querySelectorAll('[data-token]').forEach(b=>b.onclick=()=>{if(answered)return;built.push(Number(b.dataset.token));b.disabled=true;$('#built-sentence').textContent=built.map(i=>ex.tokens[i]).join(' ');});$('#reset-build').onclick=renderExercise;$('#check-build').onclick=()=>checkExercise(built.map(i=>ex.tokens[i]).join(' '));}
else{controls.innerHTML=`<form id="grammar-answer"><label class="sr-only" for="grammar-input">Answer</label><input id="grammar-input" required autocomplete="off"><button style="margin-top:12px">${esc(App.t('submit'))}</button></form>`;$('#grammar-answer').onsubmit=e=>{e.preventDefault();checkExercise($('#grammar-input').value);};}}
async function checkExercise(answer){if(answered||!answer.trim())return;if(!Auth.require())return;answered=true;const ex=currentLesson.exercises[exerciseIndex],id=currentLesson.id,index=exerciseIndex,user=Auth.user;let good=false,explanation=lessonText(ex.explanation),correct=Array.isArray(ex.answers)?ex.answers:ex.answer?[ex.answer]:[];try{if(correct.length){const norm=v=>String(v).trim().toLocaleLowerCase('de').normalize('NFC').replace(/[.!?]+$/,'').replace(/\s+/g,' ');good=correct.some(a=>norm(a)===norm(answer));}else{$('#exercise-feedback').textContent='AI…';const data=await App.evaluate(`Check this German grammar exercise. Return {"correct":true,"explanation":"...","suggestedAnswer":"..."}. No source answer key is available; label your answer as an AI suggestion. ${JSON.stringify({exercise:ex,answer})}`);good=data.correct===true;explanation='AI · '+(data.explanation||'');correct=[data.suggestedAnswer||'AI'];}if(Auth.user!==user||currentLesson?.id!==id||exerciseIndex!==index)return;const attempts=Auth.get('grammarAttempts',[]);attempts.push({lessonId:id,index,answer,correct:good,tag:currentLesson.tag||currentLesson.title,time:Date.now()});Auth.set('grammarAttempts',attempts.slice(-1000));if(good)App.event(`grammar:${id}:${index}:${App.day()}`,'grammar',5,currentLesson.tag||currentLesson.title);$('#exercise-feedback').innerHTML=`<div class="answer-message"><strong class="${good?'correct':'incorrect'}">${good?'✓ Richtig!':'✕ Noch einmal üben.'}</strong><br>${esc(App.t('answer'))}: ${esc(correct.join(' / '))}<br>${esc(explanation)}</div><button id="next-exercise">${esc(App.t('next'))} →</button>`;$('#next-exercise').onclick=()=>{exerciseIndex++;renderExercise();};}catch(error){if(user===Auth.user){answered=false;$('#exercise-feedback').textContent=error.message;}}}
$('#grammar-folder').onchange=()=>{currentLesson=null;renderLessonList();openLesson(grammarItems()[0]?.id);};$('#grammar-level').onchange=renderLessonList;
function loadGrammar(){renderGrammarFolders();renderLessonList();if(!currentLesson||!grammarItems().some(l=>l.id===currentLesson.id))openLesson(grammarItems()[0]?.id);else renderLesson();$('#grammar-intro').textContent={vi:'Import tài liệu của bạn. AI phân loại từng chủ điểm, bổ sung lý thuyết và tạo bài tập.',en:'Import your material. AI organizes grammar topics, fills theory gaps and creates exercises.',de:'Importiere dein Material. KI ordnet Grammatikthemen, ergänzt Erklärungen und erstellt Übungen.'}[App.settings().language];}
ImportHub.mount('grammar',c=>{renderGrammarFolders();$('#grammar-folder').value=c.id;openLesson(c.items[0]?.id);});document.addEventListener('authchange',()=>{currentLesson=null;loadGrammar();});document.addEventListener('languagechange',loadGrammar);loadGrammar();

let enrichingGrammar=false;
async function enrichCurrentLesson(){if(enrichingGrammar||!Auth.require()||!currentLesson)return;const user=Auth.user,folder=$('#grammar-folder').value,id=currentLesson.id,lesson=structuredClone(currentLesson);enrichingGrammar=true;$('#grammar-enrich').disabled=true;$('#grammar-enrich-status').textContent='AI…';try{const extra=await GrammarImport.enrich(lesson);if(user!==Auth.user)return;const collections=Auth.get('materials',[]),collection=collections.find(c=>c.type==='grammar'&&c.id===folder),target=collection?.items.find(l=>l.id===id);if(!target)return;target.aiAdditions=[...(target.aiAdditions||[]),...extra.additions];target.exercises=[...(target.exercises||[]),...extra.exercises];delete target.enrichmentError;Auth.set('materials',collections);if($('#grammar-folder').value===folder&&currentLesson?.id===id){currentLesson=target;renderLesson();renderLessonList();}}catch(error){if(user===Auth.user&&currentLesson?.id===id)$('#grammar-enrich-status').textContent=error.message;}finally{enrichingGrammar=false;if($('#grammar-enrich'))$('#grammar-enrich').disabled=false;}}
